@@ -0,0 +1,237 @@
+// KS-938 - "MFA disabled" left the TOTP seed and the hashed backup codes in the row.
+//
+// MECHANISM (the ticket's own measurement, re-driven here): userRepo.updateUser builds its SET list
+// with `if (tsField in updates && updates[tsField] !== undefined)`. mfa_secret and mfa_backup_codes
+// ARE in fieldMap, so the map was never the problem - the VALUE guard was. All three MFA-clearing
+// sites passed `undefined`, so a PARTIAL update landed naming only the fields that survived, the
+// call answered 200 "MFA disabled successfully", and a live re-armable seed plus unspent backup
+// codes stayed in the row. The case that matters is the user who disabled MFA BECAUSE the
+// authenticator was compromised.
+//
+// THE FIX IS PER-SITE, NOT ONE SHARED EDIT, and these cells are built to prove that:
+//   mfa.ts  :245/:248  setup-verify REVERT      (userRepo.updateUser)
+//   mfa.ts  :385/:387  POST /mfa/disable        (userRepo.updateUserOrThrow)
+//   users.ts:1118/:1122 POST /me/mfa/disable    (userRepo.updateUserOrThrow) - this site did not
+//                       pass mfaBackupCodes AT ALL, so the KEY had to be added, not just re-valued.
+//
+// updateUser's `undefined` skip is DELIBERATELY NOT CHANGED: every other caller relies on it to
+// express "leave this column alone". `null` passes the guard and writes SQL NULL, and the
+// encryption branch guards on `typeof val === 'string'` so a null can never enter it. The codebase
+// already knew the rule - wallet.ts carries "null, NOT undefined" for walletAddress (KS 720).
+//
+// WHAT THESE CELLS DRIVE: the REAL route handlers over REAL loopback HTTP, the REAL userRepo and the
+// REAL updateUser, with only `../db` stubbed so the emitted SQL can be captured. They assert the
+// STATEMENT, not the source text - a source-text assertion would still pass if the fix were
+// commented out. Arm 4 is the control that makes the other three mean something: driven with
+// `undefined` instead of `null`, through the same real updateUser, the two columns must STILL be
+// absent. A cell that cannot tell the fix from its own fallback is not a regression test.
+import { describe, it, expect, beforeAll, afterAll, beforeEach, vi } from 'vitest';
+import type { AddressInfo } from 'node:net';
+import type { Server } from 'node:http';
+import express from 'express';
+import { generateTotpCode } from '../services/totp';
+
+const SEED = 'JBSWY3DPEHPK3PXP';
+const USER_ID = 'ks938-mfa-user';
+
+/** Every statement the routes issue, in order, with params - the subject of every assertion here. */
+const sql = vi.hoisted(() => ({ calls: [] as Array<{ text: string; params: unknown[] }> }));
+/** Per-cell switches the ../db stub reads. */
+const state = vi.hoisted(() => ({ failPendingDelete: false, pendingSecret: 'JBSWY3DPEHPK3PXP' }));
+
+vi.mock('@secuura/shared', async (importOriginal) => {
+  const actual = await importOriginal<Record<string, unknown>>();
+  return {
+    ...actual,
+    encryptField: (v: string) => v,
+    decryptField: (v: string) => v,
+    encryptFieldWithDek: (v: string) => v,
+    decryptFieldWithDek: (v: string) => v,
+    isSubjectDekCiphertext: (v: unknown) => typeof v === 'string' && v.startsWith('sdek:'),
+    isEncryptedPii: () => false,
+    lookupHash: (v: string) => 'hash:' + v,
+  };
+});
+
+vi.mock('../services/subjectDeks', () => ({
+  subjectDeks: {
+    getDek: vi.fn(async () => Buffer.from('ks938-throwaway-dek')),
+    getOrCreateDek: vi.fn(async () => Buffer.from('ks938-throwaway-dek')),
+  },
+}));
+
+vi.mock('../utils/logger', () => ({
+  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
+}));
+
+// The ONLY stub in the path. It records every statement, then answers the minimum each route needs.
+vi.mock('../db', () => ({
+  query: vi.fn(async (text: string, params: unknown[] = []) => {
+    const t = String(text);
+    sql.calls.push({ text: t, params });
+
+    // The revert arm: deletePendingSetup must THROW so the compensating revert runs.
+    if (t.includes('DELETE FROM mfa_pending_setups')) {
+      if (state.failPendingDelete) throw new Error('ks938: pending-setup cleanup failed');
+      return { rows: [], rowCount: 1 };
+    }
+    if (t.includes('mfa_pending_setups')) {
+      return {
+        rows: [{ secret: state.pendingSecret, expires_at: new Date(Date.now() + 9 * 60_000).toISOString() }],
+        rowCount: 1,
+      };
+    }
+    if (t.startsWith('UPDATE users')) {
+      return { rows: [{ id: USER_ID }], rowCount: 1 };
+    }
+    if (t.includes('FROM users')) {
+      return {
+        rows: [{
+          id: USER_ID, email: 'ks938@example.test', status: 'active', role: 'user',
+          mfa_enabled: true, mfa_secret: SEED, mfa_backup_codes: ['h1', 'h2'],
+          password_hash: null, verification_level: 'standard',
+          created_at: '2026-01-01T00:00:00.000Z', updated_at: '2026-01-01T00:00:00.000Z',
+        }],
+        rowCount: 1,
+      };
+    }
+    return { rows: [], rowCount: 0 };
+  }),
+}));
+
+vi.mock('../middleware/authenticate', () => {
+  const inject = () => (req: any, _res: any, next: () => void) => {
+    req.user = { userId: USER_ID, role: 'user' };
+    next();
+  };
+  return { authenticate: inject, authenticateAccessOrConnector: inject };
+});
+
+let server: Server;
+let base = '';
+let updateUser: any;
+
+beforeAll(async () => {
+  const { mfaRoutes } = await import('../routes/mfa');
+  const { userRoutes } = await import('../routes/users');
+  const { errorHandler } = await import('../middleware/errorHandler');
+  updateUser = (await import('../repositories/userRepo')).updateUser;
+  const app = express();
+  app.use(express.json());
+  app.use('/api/auth/mfa', mfaRoutes);
+  app.use('/api/users', userRoutes);
+  app.use(errorHandler);
+  await new Promise<void>((resolve) => {
+    server = app.listen(0, '127.0.0.1', () => {
+      base = 'http://127.0.0.1:' + String((server.address() as AddressInfo).port);
+      resolve();
+    });
+  });
+});
+
+afterAll(async () => {
+  await new Promise<void>((resolve) => server.close(() => resolve()));
+});
+
+beforeEach(() => {
+  sql.calls = [];
+  state.failPendingDelete = false;
+  vi.clearAllMocks();
+});
+
+async function post(path: string, body: Record<string, unknown>) {
+  const res = await fetch(base + path, {
+    method: 'POST',
+    headers: { 'content-type': 'application/json' },
+    body: JSON.stringify(body),
+  });
+  return { status: res.status, body: await res.json().catch(() => null) };
+}
+
+/** The UPDATE statements that touched the users table, in order. */
+function userUpdates() {
+  return sql.calls.filter((c) => c.text.startsWith('UPDATE users'));
+}
+
+/** The UPDATE that CLEARS mfa (mfa_enabled = false), i.e. the one each site under test issues. */
+function clearingUpdate() {
+  return userUpdates().find((c) => c.params.includes(false));
+}
+
+describe('KS-938 - clearing MFA must NULL the TOTP seed and the hashed backup codes, at all three sites', () => {
+  it('RED KS-938 site 1 - the setup-verify REVERT names mfa_secret AND mfa_backup_codes, both NULL', async () => {
+    state.failPendingDelete = true;
+    const r = await post('/api/auth/mfa/setup/verify', { totpCode: generateTotpCode(SEED) });
+    // The route still reports the cleanup failure to the user; that is KS-1052's contract, not ours.
+    expect(r.status, 'the setup/verify status when pending-setup cleanup fails').toBe(400);
+
+    const upd = userUpdates().find((c) => c.params.includes(false));
+    expect(upd, 'the compensating revert must issue an UPDATE users statement').toBeDefined();
+    expect(upd!.text, 'the revert must name mfa_secret').toContain('mfa_secret =');
+    expect(upd!.text, 'the revert must name mfa_backup_codes').toContain('mfa_backup_codes =');
+    expect(upd!.params, 'the revert must send NULL for both columns').toContain(null);
+    expect(
+      upd!.params.filter((p) => p === null).length,
+      'BOTH cleared columns must be null, not just one',
+    ).toBeGreaterThanOrEqual(2);
+  });
+
+  it('RED KS-938 site 2 - POST /api/auth/mfa/disable names mfa_secret AND mfa_backup_codes, both NULL', async () => {
+    const r = await post('/api/auth/mfa/disable', { totpCode: generateTotpCode(SEED) });
+    expect(r.status, 'the mfa/disable status on a valid TOTP code').toBe(200);
+
+    const upd = clearingUpdate();
+    expect(upd, 'the disable route must issue an UPDATE users statement').toBeDefined();
+    expect(upd!.text, 'the disable must name mfa_secret').toContain('mfa_secret =');
+    expect(upd!.text, 'the disable must name mfa_backup_codes').toContain('mfa_backup_codes =');
+    expect(
+      upd!.params.filter((p) => p === null).length,
+      'BOTH the seed and the backup codes must be sent as NULL',
+    ).toBeGreaterThanOrEqual(2);
+  });
+
+  it('RED KS-938 site 3 - POST /api/users/me/mfa/disable names mfa_backup_codes, the key that was ABSENT', async () => {
+    const r = await post('/api/users/me/mfa/disable', { code: generateTotpCode(SEED) });
+    expect(r.status, 'the me/mfa/disable status on a valid TOTP code').toBe(200);
+
+    const upd = clearingUpdate();
+    expect(upd, 'the users disable route must issue an UPDATE users statement').toBeDefined();
+    expect(upd!.text, 'the users disable must name mfa_secret').toContain('mfa_secret =');
+    // This is the assertion that would have stayed red even after a value-only fix: the key was
+    // never in the object at this site, so no change to updateUser or to the value could add it.
+    expect(upd!.text, 'the users disable must name mfa_backup_codes - the key was absent here').toContain('mfa_backup_codes =');
+    expect(
+      upd!.params.filter((p) => p === null).length,
+      'BOTH columns must be NULL at this site too',
+    ).toBeGreaterThanOrEqual(2);
+  });
+
+  it('CONTROL - the SAME real updateUser still SKIPS an `undefined` field, so the cells above test the fix and not the fallback', async () => {
+    sql.calls = [];
+    await updateUser(USER_ID, {
+      mfaEnabled: false,
+      mfaSecret: undefined,
+      mfaBackupCodes: undefined,
+      verificationLevel: 'BASIC',
+    } as any);
+
+    const upd = userUpdates()[0];
+    expect(upd, 'the undefined shape must still issue a statement').toBeDefined();
+    expect(upd.text, 'mfa_enabled is named, so the statement did land').toContain('mfa_enabled =');
+    // The defect, preserved as a control: `undefined` is skipped and a PARTIAL update lands.
+    expect(upd.text, 'an undefined mfaSecret must still be SKIPPED - this is the semantics we did not change').not.toContain('mfa_secret =');
+    expect(upd.text, 'an undefined mfaBackupCodes must still be SKIPPED').not.toContain('mfa_backup_codes =');
+  });
+
+  it('CONTROL - an unrelated caller is untouched: a verificationLevel-only update gains no mfa columns', async () => {
+    sql.calls = [];
+    await updateUser(USER_ID, { verificationLevel: 'BASIC' } as any);
+
+    const upd = userUpdates()[0];
+    expect(upd, 'the unrelated update must issue a statement').toBeDefined();
+    expect(upd.text, 'it names the column it was given').toContain('verification_level =');
+    expect(upd.text, 'it must NOT acquire mfa_secret - the fix is scoped to the three call sites').not.toContain('mfa_secret =');
+    expect(upd.text, 'it must NOT acquire mfa_backup_codes').not.toContain('mfa_backup_codes =');
+    expect(upd.params, 'it must send no NULL it was not given').not.toContain(null);
+  });
+});
